const TARGET_COUNT = 50;
const MAX_BATCHES = 20;
const MAX_NO_PROGRESS_BATCHES = 3;

await tobub.atoms.navigate({ url: 'https://www.toutiao.com', waitUntil: 'domcontentloaded' });
await tobub.atoms.waitFor({ delay: [1800, 2800] });

function readHotBatchInBrowser() {
  const normalize = value => String(value || '').replace(/\s+/g, ' ').trim();
  const isVisible = element => {
    const rect = element.getBoundingClientRect();
    const style = getComputedStyle(element);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const buttons = Array.from(document.querySelectorAll('button,[role="button"]'))
    .filter(button => isVisible(button) && normalize(button.innerText || button.textContent) === '换一换');
  const headings = Array.from(document.querySelectorAll('h1,h2,h3,h4,[role="heading"],div,span'))
    .filter(element => isVisible(element)
      && element.children.length === 0
      && normalize(element.innerText || element.textContent) === '头条热榜');

  const candidates = [];
  for (const heading of headings) {
    let root = heading;
    for (let depth = 0; depth < 10 && root; depth++, root = root.parentElement) {
      const refreshButton = buttons.find(button => root.contains(button));
      if (!refreshButton) continue;
      const links = Array.from(root.querySelectorAll('a[href]'))
        .filter(link => isVisible(link)
          && normalize(link.innerText || link.textContent)
          && /\/(?:trending|article)\/\d+|\/a\d+\/|\/w\/\d+/i.test(link.href));
      if (links.length < 5 || links.length > 20) continue;

      const rect = heading.getBoundingClientRect();
      candidates.push({
        heading,
        root,
        refreshButton,
        links,
        rightSide: rect.left + rect.width / 2 >= window.innerWidth * 0.5,
        inViewport: rect.top >= 0 && rect.top < window.innerHeight,
        top: rect.top
      });
      break;
    }
  }

  candidates.sort((left, right) => {
    if (left.rightSide !== right.rightSide) return left.rightSide ? -1 : 1;
    if (left.inViewport !== right.inViewport) return left.inViewport ? -1 : 1;
    return left.top - right.top;
  });
  const chosen = candidates[0];
  if (!chosen) {
    return {
      found: false,
      headingCount: headings.length,
      refreshButtonCount: buttons.length
    };
  }

  const itemsById = new Map();
  for (const link of chosen.links) {
    const url = link.href;
    const match = url.match(/\/(?:trending|article)\/(\d+)/i)
      || url.match(/\/a(\d+)/i)
      || url.match(/\/w\/(\d+)/i);
    const id = match ? String(match[1]) : '';
    if (!id) continue;

    const card = link.closest('li') || link.parentElement?.parentElement || link.parentElement;
    const hotText = normalize(card?.innerText || link.innerText || link.textContent);
    let rank = null;
    try {
      const parsed = new URL(url);
      const rankFromUrl = Number(parsed.searchParams.get('rank'));
      if (Number.isInteger(rankFromUrl) && rankFromUrl > 0) rank = rankFromUrl;
    } catch {}
    if (rank === null) {
      const rankMatch = hotText.match(/(?:^|\s)(\d{1,2})(?=\s|$)/);
      if (rankMatch) rank = rankMatch ? Number(rankMatch[1]) : null;
    }
    if (rank === null || rank < 1 || rank > 50) continue;

    const rawTitle = normalize(link.innerText || link.textContent);
    const title = rawTitle.replace(/^\s*\d{1,2}\s+/, '').trim();
    if (!title) continue;
    const previous = itemsById.get(id);
    if (!previous || title.length > previous.title.length) {
      itemsById.set(id, {
        id,
        title,
        url,
        rank,
        hot_text: hotText.slice(0, 240)
      });
    }
  }

  return {
    found: true,
    headingText: normalize(chosen.heading.innerText || chosen.heading.textContent),
    rightSide: chosen.rightSide,
    items: Array.from(itemsById.values()).sort((left, right) => left.rank - right.rank)
  };
}

async function readHotBatch() {
  const result = await tobub.atoms.evaluate({
    expression: '(' + readHotBatchInBrowser.toString() + ')()'
  });
  return result.value ?? { found: false, items: [] };
}

const records = [];
const databaseObservationIds = [];
const seenIds = new Set();
let duplicateCount = 0;
let failedCount = 0;
let failedSaveCount = 0;
let refreshClicks = 0;
let rounds = 0;
let noProgressBatches = 0;
let completionReason = 'no_progress';
let batch = await readHotBatch();

if (!batch.found || !Array.isArray(batch.items) || batch.items.length === 0) {
  throw new Error('首页没有找到右侧“头条热榜”的有效排名链接：' + JSON.stringify({
    headingCount: batch.headingCount,
    refreshButtonCount: batch.refreshButtonCount
  }));
}

for (let batchNumber = 1; batchNumber <= MAX_BATCHES && records.length < TARGET_COUNT; batchNumber++) {
  if (!batch.found || !Array.isArray(batch.items) || batch.items.length === 0) {
    completionReason = 'page_error';
    break;
  }
  rounds++;
  let newRecordsThisBatch = 0;

  for (let position = 0; position < batch.items.length && records.length < TARGET_COUNT; position++) {
    const item = batch.items[position];
    const id = String(item.id || '').trim();
    const title = String(item.title || '').trim();
    const url = String(item.url || '').trim();
    const rank = Number(item.rank);
    if (!id || !title || !/^https?:\/\//i.test(url) || !Number.isInteger(rank) || rank < 1 || rank > 50) {
      failedCount++;
      continue;
    }
    if (seenIds.has(id)) {
      duplicateCount++;
      continue;
    }
    seenIds.add(id);

    const record = {
      id,
      title,
      url,
      rank,
      batch_number: batchNumber,
      batch_position: position + 1,
      hot_text: String(item.hot_text || '').slice(0, 240)
    };
    try {
      const saved = await tobub.db.saveContent({
        platform: 'toutiao',
        contentType: 'article',
        externalId: record.id,
        title: record.title,
        summary: record.hot_text,
        url: record.url,
        metadata: {
          source: 'toutiao-hot-rank',
          rank: record.rank,
          batchNumber: record.batch_number,
          batchPosition: record.batch_position,
          hotText: record.hot_text
        },
        rawData: record,
        observationSource: 'toutiao-hot-rank',
        observationMeta: {
          batchNumber: record.batch_number,
          batchPosition: record.batch_position,
          rank: record.rank
        }
      });
      if (!saved || !saved.observationId || !saved.contentItemId) {
        throw new Error('tobub.db.saveContent did not return a content observation.');
      }
      records.push({
        ...record,
        content_item_id: saved.contentItemId,
        observation_id: saved.observationId
      });
      databaseObservationIds.push(saved.observationId);
      newRecordsThisBatch++;
    } catch {
      failedCount++;
      failedSaveCount++;
    }
  }

  if (records.length >= TARGET_COUNT) {
    completionReason = 'target_reached';
    break;
  }
  noProgressBatches = newRecordsThisBatch > 0 ? 0 : noProgressBatches + 1;
  if (noProgressBatches >= MAX_NO_PROGRESS_BATCHES) {
    completionReason = 'no_progress';
    break;
  }

  const previousFingerprint = batch.items.map(item => String(item.id || '')).join('|');
  try {
    await tobub.atoms.click(
      { role: 'button', name: '换一换', exact: true },
      { timeout: 10000 }
    );
  } catch {
    completionReason = 'page_error';
    break;
  }
  refreshClicks++;

  let nextBatch = null;
  for (let attempt = 0; attempt < 18; attempt++) {
    await tobub.atoms.waitFor({ delay: [500, 800] });
    const candidate = await readHotBatch();
    const fingerprint = Array.isArray(candidate.items)
      ? candidate.items.map(item => String(item.id || '')).join('|')
      : '';
    if (candidate.found && fingerprint && fingerprint !== previousFingerprint) {
      nextBatch = candidate;
      break;
    }
  }
  if (!nextBatch) {
    completionReason = 'no_progress';
    break;
  }
  batch = nextBatch;
}

if (records.length >= TARGET_COUNT && failedSaveCount === 0) completionReason = 'target_reached';
else if (failedSaveCount > 0) completionReason = 'database_error';
else if (rounds >= MAX_BATCHES) completionReason = 'round_limit';

const status = records.length === TARGET_COUNT && failedCount === 0 ? 'ok' : records.length > 0 ? 'partial' : 'empty';
return {
  status,
  target: TARGET_COUNT,
  collected: records.length,
  persisted: databaseObservationIds.length,
  database_observations: databaseObservationIds,
  rounds,
  refresh_clicks: refreshClicks,
  duplicates: duplicateCount,
  failed: failedCount,
  failed_saves: failedSaveCount,
  completion_reason: completionReason,
  source_url: 'https://www.toutiao.com',
  records
};
